const $=id=>document.getElementById(id);
let selected=0,current=null,busy=false,loading=false,ollamaReady=false;
const statuses={baseline:'기본 답변',generic_unverified:'일반 수정',revised_unvalidated:'수정 채택',unchanged:'원래 답변 유지',needs_context:'추가 맥락 필요',retained:'수정안 보류',retained_error:'점검 실패 · 원래 답변 유지',failed:'생성 실패'};
function inputs(){const question=$('question').value.trim();return{question,context:'',concepts:'',language:/[가-힣ㄱ-ㅎㅏ-ㅣ]/.test(question)?'한국어':'English'}}
function isExample(){return ['question','context','concepts'].every(k=>inputs()[k]===examples[selected][k]);}
function ready(){return $('backend').value==='browser'?ContextRuntime.ready():ollamaReady;}
function label(){if(!busy&&!loading)$('run').textContent='실행';}
function render(result,demo=false){current={...result,demo};$('meta-mode').textContent=demo?'작성 예시':({baseline:'기본 생성',generic:'일반 자기점검',grounded:'원문 근거 기반 수정'}[result.mode]||'—');$('meta-model').textContent=demo?'실제 추론 없음':result.runtime?.model||'정보 없음';$('meta-calls').textContent=demo?'—':String(result.trace?.length||0);$('copy').textContent='최종 출력 복사';$('meta-time').textContent=demo?'—':((result.trace||[]).reduce((sum,t)=>sum+(t.elapsed_ms||0),0)/1000).toFixed(1)+' s';$('result-badge').textContent=demo?'작성된 예시 · 실측 아님':statuses[result.status]||result.status;$('draft').textContent=result.draft||'생성된 답변이 없습니다.';$('final').textContent=result.final||'완료된 답변이 없습니다.';$('issues').replaceChildren();const issues=result.issues||[];$('issue-count').textContent=`${issues.length}개 점검`;issues.forEach((issue,index)=>{const div=document.createElement('div');div.className='issue';const number=document.createElement('span');number.className='issue-number';number.textContent=String(index+1).padStart(2,'0');const body=document.createElement('div');const h=document.createElement('h4');h.textContent=issue.problem;const q=document.createElement('blockquote');q.textContent='초안: '+issue.quote;const p=document.createElement('p');p.textContent=issue.suggestion;body.append(h,q,p);if(issue.source_quote){const evidence=document.createElement('blockquote');evidence.textContent=`원문 [${issue.source_id}]: ${issue.source_quote}`;body.append(evidence);}div.append(number,body);$('issues').append(div);});if(!issues.length){const p=document.createElement('p');p.className='empty-note';p.textContent=result.mode==='baseline'?'기본 조건에서는 점검하지 않습니다.':result.mode==='generic'?'일반 자기점검 조건입니다. 구조화된 원문 대조를 하지 않습니다.':'검출 항목 없음';$('issues').append(p);}$('questions').textContent=(result.questions||[]).join('\n');$('questions').hidden=!result.questions?.length;$('verdict').textContent=result.verification?.reason||result.error||'';$('verdict').hidden=!$('verdict').textContent;$('candidate-box').hidden=!result.candidate||result.candidate===result.final;$('candidate').textContent=result.candidate||'';$('export').disabled=demo;$('copy').disabled=!result.final;}
function loadExample(index){selected=index;const e=examples[index];$('question').value=e.question+'\n'+e.context+'\n'+e.concepts;document.querySelectorAll('[data-example]').forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-pressed',String(i===index))});$('error').hidden=true;$('result-badge').textContent='입력 변경 · 실행 전';label();}
function error(message){$('error').textContent=message;$('error').hidden=false;}
function lock(value){busy=value;document.querySelectorAll('textarea,.chip,#connect,#mode,#language,#run').forEach(e=>e.disabled=value);$('stop').hidden=!value;$('progress').hidden=!value;label();}
async function checkOllama(){ollamaReady=false;if(location.protocol==='file:'){$('connection-status').textContent='Ollama 연결은 동봉한 로컬 실행기로 열었을 때 사용할 수 있습니다. HTML 직접 열기에서는 브라우저 모델을 선택하세요.';return;}try{const response=await fetch('/api/models',{signal:AbortSignal.timeout(4000)});if(!response.ok)throw Error();const data=await response.json();if(!Array.isArray(data.models)||!data.models.length)throw Error();ollamaReady=true;if(!$('model').value)$('model').value=data.models[0].name;$('connection-status').textContent='로컬 Ollama 연결됨';}catch{$('connection-status').textContent='Ollama 연결을 찾지 못했습니다. 브라우저 모델은 별도 설치 없이 사용할 수 있습니다.';}label();}
async function diagnose(){if($('backend').value==='ollama')return checkOllama();const report=await ContextRuntime.diagnose().catch(e=>({ok:false,message:e.message}));$('connection-status').textContent=ContextRuntime.ready()?'브라우저 모델 준비 완료: '+ContextRuntime.model():report.message;return report;}
async function ollama(system,payload,schema){const model=$('model').value.trim();if(!model)throw Error('Ollama 모델 이름을 입력해 주세요.');const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model,messages:[{role:'system',content:system},{role:'user',content:JSON.stringify(payload)}],stream:false,options:{temperature:ContextGuard.CONFIG.temperature,seed:ContextGuard.CONFIG.seed,num_predict:ContextGuard.CONFIG.maxTokens},...(schema?{format:schema}:{})}),signal:AbortSignal.timeout(240000)});const data=await response.json();if(!response.ok||data.error)throw Error(data.error||'Ollama 요청 실패');if(!data.done||data.done_reason==='length'||!data.message?.content?.trim())throw Error('Ollama 응답이 비어 있거나 잘렸습니다.');return data.message.content;}
let stopped=false;
async function run(){if(busy||loading)return;$('error').hidden=true;if(!inputs().question){error('질문을 입력해 주세요.');return;}try{ContextGuard.makeSource(inputs());}catch(e){error(e.message);return;}lock(true);$('result-badge').textContent='자동 처리 중';stopped=false;ContextRuntime.begin();const start=new Date().toISOString();try{if(!ready()){if($('backend').value==='ollama'){await checkOllama();if(!ollamaReady)throw Error('Ollama 연결을 확인해 주세요.');}else{await ContextRuntime.load('balanced',text=>{$('progress').textContent=text;});if(stopped)throw Error('분석을 중단했습니다.');}}const base=$('backend').value==='browser'?ContextRuntime.complete:ollama;const complete=async(...args)=>{if(stopped)throw Error('분석을 중단했습니다.');const r=await base(...args);if(stopped)throw Error('분석을 중단했습니다.');return r;};const result=await ContextGuard.run(inputs(),complete,{mode:$('mode').value,onProgress:stage=>{$('progress').textContent=stage+' · 로컬 모델이 처리하고 있습니다…';}});result.runtime={backend:$('backend').value,model:$('backend').value==='browser'?ContextRuntime.model():$('model').value,started_at:start,finished_at:new Date().toISOString(),generation:ContextGuard.CONFIG};render(result);if(result.error)error(result.error);}catch(e){$('result-badge').textContent='실행 실패 · 새 결과 없음';error(e.message);}finally{lock(false);}}
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>loadExample(Number(b.dataset.example)));
document.querySelectorAll('textarea').forEach(t=>t.oninput=()=>{$('result-badge').textContent='이전 결과 · 새 입력 미반영';document.querySelectorAll('.chip').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});label();});
for(const id of ['mode','language'])$(id).onchange=()=>{$('result-badge').textContent='이전 결과 · 설정 변경 미반영';label();};
$('question-form').onsubmit=e=>{e.preventDefault();run();};$('connect').onclick=()=>{$('settings').showModal();diagnose();};$('backend').onchange=()=>{$('browser-options').hidden=$('backend').value!=='browser';$('ollama-options').hidden=$('backend').value!=='ollama';diagnose();label();};$('refresh').onclick=checkOllama;
$('load-model').onclick=async()=>{if(loading||busy)return;loading=true;$('load-model').disabled=true;$('backend').disabled=true;$('browser-model').disabled=true;$('run').disabled=true;try{await ContextRuntime.load($('browser-model').value,text=>$('connection-status').textContent=text);$('connection-status').textContent='준비 완료. 이 창을 닫고 질문을 분석하세요.';$('run-note').textContent='모델 준비 완료';}catch(e){$('connection-status').textContent='준비 실패: '+e.message+' 파일 직접 열기에서 실패하면 동봉한 로컬 실행기로 열어 주세요.';}finally{loading=false;$('load-model').disabled=false;$('backend').disabled=false;$('browser-model').disabled=false;$('run').disabled=false;label();}};
$('stop').onclick=()=>{stopped=true;ContextRuntime.cancel();$('progress').textContent='중단 요청됨 · 현재 호출 종료를 기다립니다.';};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(current.final);$('copy').textContent='복사 완료';}catch{$('copy').textContent='답변을 직접 선택해 복사하세요.';}};
$('export').onclick=()=>{if(!current||current.demo)return;const blob=new Blob([JSON.stringify(current,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='context-lab-result-'+Date.now()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('question').value='';$('draft').textContent='—';$('final').textContent='—';$('issues').textContent='실행 대기';$('issue-count').textContent='';$('result-badge').textContent='입력 대기';$('meta-mode').textContent='자동 점검';$('meta-model').textContent='실행 시 자동 준비';$('meta-calls').textContent='—';$('copy').disabled=true;label();
